import { forwardRef, type TextareaHTMLAttributes, type ReactNode } from "react";
import { type LucideIcon } from "lucide-react";
import { twMerge } from "tailwind-merge";
import {
  TRN_INPUT_CONTROL_CLASS,
  trnInputRowClass,
  trnInputTextSizeClass,
  type TRNInputSize,
  type TRNInputVariant,
} from "./trnInputClasses.js";
import {
  renderTrnInputPrefixIcon,
  resolveTrnFieldTextPrefixIcon,
} from "./trnFieldTextPrefixIcon.js";

export type TRNTextareaProps = Omit<TextareaHTMLAttributes<HTMLTextAreaElement>, "size"> & {
  /** Lucide component or custom React node. Overrides the default field Type prefix when set. */
  prefixIcon?: LucideIcon | ReactNode;
  /** When `variant="field"`, show the default Type prefix unless overridden. Set `false` to hide. */
  showPrefixIcon?: boolean;
  size?: TRNInputSize;
  variant?: TRNInputVariant;
  invalid?: boolean;
  /** Wrapper chrome (not the native textarea). */
  className?: string;
  textareaClassName?: string;
};

export const TRNTextarea = forwardRef<HTMLTextAreaElement, TRNTextareaProps>(
  function TRNTextarea(props, ref) {
    const {
      prefixIcon,
      showPrefixIcon,
      size = "sm",
      variant = "outlined",
      invalid = false,
      className,
      textareaClassName,
      disabled,
      rows = 4,
      ...textareaRest
    } = props;

    const rowClass = twMerge(
      trnInputRowClass(variant, size, invalid, disabled === true),
      "items-stretch",
      className,
    );

    const controlClass = twMerge(
      TRN_INPUT_CONTROL_CLASS,
      trnInputTextSizeClass(size, variant),
      "min-h-0 resize-y py-1.5 text-zinc-100",
      textareaClassName,
    );

    const resolvedPrefixIcon = resolveTrnFieldTextPrefixIcon({
      variant,
      prefixIcon,
      showPrefixIcon,
      type: "text",
    });

    return (
      <div className={rowClass}>
        {resolvedPrefixIcon != null ? (
          <span className="inline-flex shrink-0 self-start pt-1.5">
            {renderTrnInputPrefixIcon(resolvedPrefixIcon)}
          </span>
        ) : null}
        <textarea
          ref={ref}
          disabled={disabled}
          rows={rows}
          aria-invalid={invalid || undefined}
          className={controlClass}
          {...textareaRest}
        />
      </div>
    );
  },
);
